import React, { useEffect, useState } from "react";
import { useParams } from "react-router-dom";
import { useCart } from "../components/CartContext";

const API_URL = "http://localhost:5001/api/products";

const ProductDetail = () => {
  const { id } = useParams();
  const [product, setProduct] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const { addToCart } = useCart();

  useEffect(() => {
    setLoading(true);
    fetch(`${API_URL}/${id}`)
      .then((res) => {
        if (!res.ok) throw new Error("Produk tidak ditemukan");
        return res.json();
      })
      .then((data) => {
        setProduct(data);
        setError(null);
      })
      .catch((err) => {
        setError(err.message);
        setProduct(null);
      })
      .finally(() => setLoading(false));
  }, [id]);

  if (loading) return <div className="text-center py-10">Memuat...</div>;
  if (error) return <div className="text-center text-red-500 py-10">{error}</div>;
  if (!product) return null;

  return (
    <div className="max-w-3xl mx-auto py-12 px-4 bg-gray-50 dark:bg-gray-900 rounded-xl shadow transition-colors duration-[900ms] ease-in-out">
      <div className="flex flex-col md:flex-row gap-8">
        <img src={product.image} alt={product.name} className="w-64 h-64 object-contain rounded shadow bg-gray-100 dark:bg-gray-700 border transition-colors duration-[900ms] ease-in-out" />
        <div className="flex-1">
          <h1 className="text-3xl font-bold mb-3 text-gray-900 dark:text-gray-100 transition-colors duration-[900ms] ease-in-out">{product.name}</h1>
          <div className="text-xl text-blue-700 dark:text-blue-300 font-semibold mb-2 transition-colors duration-[900ms] ease-in-out">Rp {product.price.toLocaleString('id-ID')}</div>
          <div className="mb-4 text-gray-700 dark:text-gray-200 transition-colors duration-[900ms] ease-in-out">{product.description}</div>
          <table className="w-full text-sm mb-4 border-t border-b border-gray-200 dark:border-gray-700 transition-colors duration-[900ms] ease-in-out">
            <tbody>
              <tr><td className="py-1 pr-3 font-semibold text-gray-700 dark:text-gray-300">SKU</td><td className="py-1 text-gray-800 dark:text-gray-100">{product.sku || '-'}</td></tr>
              <tr><td className="py-1 pr-3 font-semibold text-gray-700 dark:text-gray-300">Kategori</td><td className="py-1 text-gray-800 dark:text-gray-100">{product.category || '-'}</td></tr>
              <tr><td className="py-1 pr-3 font-semibold text-gray-700 dark:text-gray-300">Stok</td><td className="py-1 text-gray-800 dark:text-gray-100">{product.stock || '-'}</td></tr>
              <tr><td className="py-1 pr-3 font-semibold text-gray-700 dark:text-gray-300">Berat</td><td className="py-1 text-gray-800 dark:text-gray-100">{product.weight ? product.weight + ' gr' : '-'}</td></tr>
              <tr><td className="py-1 pr-3 font-semibold text-gray-700 dark:text-gray-300">Dimensi</td><td className="py-1 text-gray-800 dark:text-gray-100">{product.dimensions || '-'}</td></tr>
            </tbody>
          </table>
          <button
            onClick={() => addToCart(product)}
            className="bg-blue-600 text-white px-6 py-2 rounded font-bold hover:bg-blue-700 transition-colors duration-[900ms] ease-in-out"
          >
            Tambah ke Keranjang
          </button>
        </div>
      </div>
    </div>
  );
};

export default ProductDetail;
